style.css:
@-moz-document domain("youtube.com") {
/* base dark mode */
  body, ytd-app {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
  }

  /* header and sidebar */
  ytd-masthead, tp-yt-app-drawer {
    background-color: #1a1a1a !important;
  }

  /* pink progress bar */
  .ytp-play-progress, .ytp-scrubber-button {
    background-color: #e19dcd !important;
  }

  /* pink like/dislike, sub button, etc. */
  ytd-toggle-button-renderer.style-default-active,
  ytd-subscribe-button-renderer paper-button {
    background-color: #e19dcd !important;
    color: black !important;
  }

  /* links and hover effects */
  a, .yt-simple-endpoint, .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal:hover {
    color: #e19dcd !important;
  }

  /* video title hover */
  a:hover, .yt-simple-endpoint:hover {
    color: #f1b9e3 !important;
  }

  /* comment like/dislike buttons active */
  #like-button[aria-pressed="true"] yt-icon,
  #dislike-button[aria-pressed="true"] yt-icon {
    color: #e19dcd !important;
  }

  /* search bar border & focus */
  #search-form input {
    border: 1px solid #e19dcd !important;
  }

  #search-form input:focus {
    outline: 2px solid #e19dcd !important;
  }

  /* subscribe button on hover */
  ytd-subscribe-button-renderer paper-button:hover {
    background-color: #f0b5e2 !important;
  }

  /* remove some red defaults */
  #progress.ytd-watch-flexy {
    --paper-progress-active-color: #e19dcd !important;
    --paper-progress-container-color: #444 !important;
  }

  /* thumbnail borders on hover */
  ytd-thumbnail:hover {
    border: 2px solid #e19dcd !important;
    box-shadow: 0 0 10px #e19dcd44;
  }
}
